import java.util.*;

class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> result = new ArrayList<>();
        backtrack(n, 0, 0, new StringBuilder(), result);
        return result;
    }

    private void backtrack(int n, int open, int close, StringBuilder path, List<String> result) {
        if (path.length() == 2 * n) {
            result.add(path.toString());
            return;
        }

        if (open < n) {
            path.append('(');
            backtrack(n, open + 1, close, path, result);
            path.deleteCharAt(path.length() - 1);
        }

        if (close < open) {
            path.append(')');
            backtrack(n, open, close + 1, path, result);
            path.deleteCharAt(path.length() - 1);
        }
    }
}

import java.util.*;

class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> result = new ArrayList<>();
        generate(n, 0, 0, "", result);
        return result;
    }

    private void generate(int n, int open, int close, String current, List<String> result) {
        if (current.length() == 2 * n) {
            result.add(current);
            return;
        }

        if (open < n) {
            generate(n, open + 1, close, current + "(", result);
        }
        if (close < open) {
            generate(n, open, close + 1, current + ")", result);
        }
    }
}

import java.util.*;

class Solution {
    private static class State {
        final String value;
        final int open;
        final int close;

        State(String value, int open, int close) {
            this.value = value;
            this.open = open;
            this.close = close;
        }
    }

    public List<String> generateParenthesis(int n) {
        List<String> result = new ArrayList<>();
        Deque<State> stack = new ArrayDeque<>();
        stack.push(new State("", 0, 0));

        while (!stack.isEmpty()) {
            State state = stack.pop();
            if (state.value.length() == 2 * n) {
                result.add(state.value);
                continue;
            }
            if (state.close < state.open) {
                stack.push(new State(state.value + ")", state.open, state.close + 1));
            }
            if (state.open < n) {
                stack.push(new State(state.value + "(", state.open + 1, state.close));
            }
        }

        return result;
    }
}

import java.util.*;

class Solution {
    public List<String> generateParenthesis(int n) {
        List<List<String>> dp = new ArrayList<>();
        dp.add(Collections.singletonList(""));

        for (int pairs = 1; pairs <= n; pairs++) {
            List<String> current = new ArrayList<>();
            for (int leftPairs = 0; leftPairs < pairs; leftPairs++) {
                int rightPairs = pairs - 1 - leftPairs;
                for (String left : dp.get(leftPairs)) {
                    for (String right : dp.get(rightPairs)) {
                        current.add("(" + left + ")" + right);
                    }
                }
            }
            dp.add(current);
        }

        return dp.get(n);
    }
}

import java.util.*;

class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> result = new ArrayList<>();
        int length = 2 * n;
        int limit = 1 << length;

        for (int mask = 0; mask < limit; mask++) {
            if (Integer.bitCount(mask) != n) {
                continue;
            }
            StringBuilder candidate = new StringBuilder();
            int balance = 0;
            boolean valid = true;
            for (int bit = length - 1; bit >= 0; bit--) {
                boolean open = ((mask >> bit) & 1) == 1;
                if (open) {
                    balance++;
                    candidate.append('(');
                } else {
                    balance--;
                    candidate.append(')');
                }
                if (balance < 0) {
                    valid = false;
                    break;
                }
            }
            if (valid && balance == 0) {
                result.add(candidate.toString());
            }
        }

        return result;
    }
}
